import{_ as i,o as s,c as t,a2 as a}from"./chunks/framework.DhQimoSI.js";const k=JSON.parse('{"title":"Core components","description":"","frontmatter":{},"headers":[],"relativePath":"guide/core-components.md","filePath":"guide/core-components.md"}'),n={name:"guide/core-components.md"};function o(h,e,d,r,l,c){return s(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="core-components" tabindex="-1">Core components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core components&quot;">​</a></h1><p>The <code>core::</code> namespace holds the components the format itself relies on: naming, placement, hierarchy and types. Every other component is ordinary data that Mosaic carries without interpreting.</p><p>Their schemas live in <a href="https://github.com/tomvandig/mosaic/tree/main/sdk/ts/src/core/schemas/" target="_blank" rel="noreferrer"><code>sdk/ts/src/core/schemas/</code></a>.</p><table tabindex="0"><thead><tr><th>Type</th><th>Has a value</th><th>What it does</th></tr></thead><tbody><tr><td><code>core::name</code></td><td>no, the name is the reference <code>id</code></td><td>A human-readable name for the node</td></tr><tr><td><code>core::child</code></td><td>no, the child&#39;s node id is the reference <code>id</code></td><td>Hangs a node beneath this one</td></tr><tr><td><code>core::inherit</code></td><td>no, the parent type&#39;s node id is the reference <code>id</code></td><td>Makes this node <em>be</em> another</td></tr><tr><td><code>core::transform</code></td><td>yes, one row in <code>core::transform.ndjson</code></td><td>The node&#39;s local placement</td></tr></tbody></table><h2 id="value-less-components" tabindex="-1">Value-less components <a class="header-anchor" href="#value-less-components" aria-label="Permalink to &quot;Value-less components&quot;">​</a></h2><p>Three of the four carry no row at all. Their reference leaves out <code>index</code> (it defaults to <code>-1</code>), and the reference <code>id</code>, which every reference has anyway, <em>is</em> the data:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;core::name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,    </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Left plinth&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;core::child&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;d6c1d2ba-9376-4461-8c56-27c496c1d2ba&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;core::inherit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;70000000-7000-4000-8000-700000000001&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>So a node can carry many of each, one per name, child or type, and a later section can drop exactly one of them with a <code>DELETE</code> on that <code>id</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;core::child&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;d6c1d2ba-9376-4461-8c56-27c496c1d2ba&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;operation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;DELETE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>It also means names, hierarchy and types can be read straight off the references, without touching a single component table. That is what lets the viewer draw a tree of a whole building without loading its geometry.</p><h2 id="core-name" tabindex="-1"><code>core::name</code> <a class="header-anchor" href="#core-name" aria-label="Permalink to &quot;`core::name`&quot;">​</a></h2><p>A human-readable name for the node. A converted glTF or IFC node keeps the name a person would recognise this way, next to the uuid the node is identified by. A node may carry several names.</p><h2 id="core-child" tabindex="-1"><code>core::child</code> <a class="header-anchor" href="#core-child" aria-label="Permalink to &quot;`core::child`&quot;">​</a></h2><p>A parent-child link. The reference <code>id</code> is the id of the child node.</p><ul><li>One node can hold many children.</li><li>A node that is someone&#39;s child is not a root of the scene.</li><li>Naming the same node from several parents places it several times. The copies share their mesh, so the geometry is stored once however often it appears, and a placed node brings its whole subtree along.</li><li>A link may cross an <a href="/mosaic/dist/docs/guide/definitions#import">import</a>: a scene can place a node that lives in another archive.</li><li>Links that would expand forever are refused. A cycle is reported with the path that closes it.</li></ul><h2 id="core-inherit" tabindex="-1"><code>core::inherit</code> <a class="header-anchor" href="#core-inherit" aria-label="Permalink to &quot;`core::inherit`&quot;">​</a></h2><p>An is-a link. The reference <code>id</code> is the id of the node to inherit from.</p><p>When composing, the node receives every component of the node it inherits from, except where it carries one under the same reference <code>id</code>. Its own always wins. So a type node can hold the mesh once, and every node that is-a that type picks it up while overriding only its transform.</p><ul><li>A node may inherit from several nodes. Where two offer the same <code>id</code>, the one named first wins.</li><li>Chains are allowed: a node that inherits from a node that inherits from a third gets all three, with the nearest winning.</li><li>The is-a links themselves come along, so a node two steps down a chain still answers to the type at the top. &quot;Everything that is a Chair&quot; is a question about nodes, not a graph walk.</li><li>Unlike <code>core::child</code>, this changes the node itself, not what hangs beneath it.</li><li>Inheritance is expanded only when composing. The file always records what was written.</li></ul><p>See <a href="/mosaic/dist/docs/guide/format#example-boxes-by-type">The format</a> for a worked example.</p><h2 id="core-transform" tabindex="-1"><code>core::transform</code> <a class="header-anchor" href="#core-transform" aria-label="Permalink to &quot;`core::transform`&quot;">​</a></h2><p>The local transform of a node, either as <code>translation</code> / <code>rotation</code> / <code>scale</code> or as a 4×4 column-major <code>matrix</code>. The field names and defaults follow the glTF 2.0 node, but a transform is not specific to glTF, which is why it lives in <code>core</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th></tr></thead><tbody><tr><td><code>translation</code></td><td><code>[x, y, z]</code></td><td><code>[0, 0, 0]</code></td></tr><tr><td><code>rotation</code></td><td>unit quaternion <code>[x, y, z, w]</code></td><td><code>[0, 0, 0, 1]</code></td></tr><tr><td><code>scale</code></td><td><code>[x, y, z]</code></td><td><code>[1, 1, 1]</code></td></tr><tr><td><code>matrix</code></td><td>16 numbers, column-major</td><td>identity</td></tr></tbody></table><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;translation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;scale&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;translation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]}</span></span></code></pre></div><p>Composing writes it straight onto the glTF node, as a <code>matrix</code> or as TRS.</p>',25)])])}const E=i(n,[["render",o]]);export{k as __pageData,E as default};
